     def solve(self):

         N, S, p = self.P[:3]
         G = sorted(self.P[3:], reverse=True)

         r = 0
         s = 0
         for g in G:
             if g >= 3 * p - 2 and g >= p:
                 r += 1
             elif g >= 3 * p - 4 and g >= p:
                 if s == S:
                     break
                 r += 1
                 s += 1

         return r


