 def calculateOneClick(R, C, M):
     size = R * C
     if R == 1 or C == 1 and M < size:
         return generateWinBoardBaseCase(R, C, M)
     elif size - M == 1:
         return generateWinBoardBaseCase(R, C, M)
     elif size - M >= 4:
         return generateWinBoard(R, C, M)
     return "Impossible"

 def generateWinBoard(R,C,M):
     emptySpace = R * C - M - 4
     out = "c"
     if C > 1:
         out += "."
         for i in range(2,C):
             if emptySpace > 0:
                 out += "."
                 emptySpace -= 1
             else:
                 out += "*"
                 # out += '\n'
     if R > 1:
         out += '\n'
         out += "."
         if C > 1:
             out += "."
         for i in range(2,C):
             if emptySpace > 0:
                 out += "."
                 emptySpace -= 1
             else:
                 out += "*"
     for r in range(2,R):
         out += '\n'
         for c in range(C):
             if emptySpace > 0:
                 out += "."
                 emptySpace -= 1
             else:
                 out += "*"
     return out

 def generateWinBoardBaseCase(R,C,M):
     emptySpace = R * C - M - 1
     out = "c"
     if C > 1:
         for c in range(1,C):
             if emptySpace > 0:
                 out += "."
                 emptySpace -= 1
             else:
                 out += "*"
     for r in range(1,R):
         out += '\n'
         for c in range(C):
             if emptySpace > 0:
                 out += "."
                 emptySpace -= 1
             else:
                 out += "*"
     return out


