#!/usr/bin/env python

 = "tiny"

 INPUT = "B-small-attempt0.in.txt"

 def debug(*args):
     pass #print str(args)

 def zdebug(*args):
     print ''.join(str(s) for s in args)

 def can_score_p(N, p):
     low_p = max(p-1, 0)
     if low_p + low_p + p <= N:
         return "Y"
     low_p = max(p-2, 0)
     if low_p + low_p + p <= N:
         return "S"
     return "N"

 def do_trial(N, S, p, *scores):
     d = { "Y" : 0, "N" : 0, "S" : 0 }
     for s in scores:
         v = can_score_p(s, p)
         debug("score %s p=%s : %s" % (s, p, v))
         d[v] = d[v] + 1
     return d["Y"] + min(d["S"], S)

