def CASE(IN):
     def rstr(): return IN.readline().strip()
     def rint(): return int(rstr())
     def rfs(): return map(float, rstr().split())
     N = rint()
     A = sorted(rfs())
     B = sorted(rfs())
     dwar = solve(N, A, B)
     war = N - solve(N, B, A)
     return "%i %i" % (dwar, war)


 def solve(N, A, B):
     i, j = 0, 0
     while True:
         while j < N and A[j] < B[i]:
             j += 1
         if j == N:
             return i
         i += 1
         j += 1


